}

// «Merge турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

const required = ["test", "build"];

const green = [
  { name: "lint", status: "passed" },
  { name: "test", status: "passed" },
  { name: "build", status: "passed" },
];

const redf = [
  { name: "lint", status: "passed" },
  { name: "test", status: "failed" },
  { name: "build", status: "passed" },
];

// build хараахан ажиллаагүй (жагсаалтад алга) — merge-г хаах ёстой.
const missing = [
  { name: "lint", status: "passed" },
  { name: "test", status: "passed" },
];

window.MERGE_GREEN = null;
window.MERGE_RED = null;
window.MERGE_MISSING = null;

try {
  window.MERGE_GREEN = canMerge(green, required);
  window.MERGE_RED = canMerge(redf, required);
  window.MERGE_MISSING = canMerge(missing, required);
  panel(window.MERGE_GREEN ? "ok" : "bad", "green", "Бүх шаардлагатай шалгалт ногоон", ["canMerge → " + String(window.MERGE_GREEN)]);
  panel(!window.MERGE_RED ? "ok" : "bad", "red", "test унасан", ["canMerge → " + String(window.MERGE_RED)]);
  panel(!window.MERGE_MISSING ? "ok" : "bad", "missing", "build хараахан ажиллаагүй", ["canMerge → " + String(window.MERGE_MISSING)]);
} catch (problem) {
  panel("bad", "error", "Алдаа", [problem.message]);
}

document.body.dataset.ready = "1";

