// Branch protection — шаардлагатай бүх шалгалт ногоон бол л merge зөвшөөрнө.

function canMerge(checks, required) {
  return required.every((name) => {
    const check = checks.find((c) => c.name === name);
    return check !== undefined && check.status === "passed";
  });
}
